pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller, uint256 value, uint256 timestamp) public {
        vm.assume(value == 10 ether);
        vm.assume(timestamp > c.pastBlockTime() || (block.timestamp > c.pastBlockTime() && timestamp >= block.timestamp));
        // Ensure the call will satisfy the timestamp require
        if (timestamp <= c.pastBlockTime()) {
            vm.warp(c.pastBlockTime() + 1);
        } else {
            vm.warp(timestamp);
        }
        uint256 balanceBefore = address(c).balance;
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: value}("");
        assertTrue(!success || address(c).balance == balanceBefore);
    }
}

