pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 blockTime, uint256 blockNumber) public {
        vm.assume(blockTime > 0);
        vm.assume(blockNumber > 0);
        vm.assume(sender != address(0));
        vm.deal(address(c), 10 ether);

        vm.warp(blockTime);
        vm.roll(blockNumber);

        uint256 balanceBefore = address(c).balance;

        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        // The bug replaces the transfer with false, so balance never decreases
        // Rule: when block.number % 15 != 0, the balance should decrease by 10 ether in reference C
        // But with the bug, balance stays the same
        vm.assume(blockNumber % 15 != 0);
        vm.assume(success);

        assertTrue(balanceAfter == balanceBefore - 10 ether, "Balance should have decreased by 10 ether");
    }
}

