pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 timeOffset, uint256 amount) public {
        vm.assume(caller != address(0) && caller != address(c));
        amount = bound(amount, 0, 100 ether);
        timeOffset = bound(timeOffset, 1, 10000);

        // Ensure time moves forward
        vm.warp(block.timestamp + timeOffset);

        uint256 balanceBefore = address(c).balance;

        // Fund the contract if needed
        if (balanceBefore < 10 ether) {
            vm.deal(address(c), 10 ether);
            balanceBefore = 10 ether;
        }

        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 balanceAfter = address(c).balance;

        if (success) {
            bool shouldTransfer = (block.number - 1) % 15 == 0;
            uint256 expectedBalance;
            if (shouldTransfer) {
                expectedBalance = 0; // all balance transferred
            } else {
                expectedBalance = balanceBefore + 10 ether;
            }
            assertTrue(balanceAfter == expectedBalance, "Balance should satisfy transfer rule");
        }
    }
}

