pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 timestamp, uint256 blockNumber) public {
        // Bound inputs to realistic values
        timestamp = bound(timestamp, 1, type(uint256).max - 1000);
        blockNumber = bound(blockNumber, 1, type(uint256).max);

        // Ensure the timestamp will satisfy the require
        vm.warp(c.pastBlockTime() + timestamp + 1);
        // Set the block number
        uint256 targetBlock = blockNumber;
        vm.roll(targetBlock);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Deal enough ether to sender
        vm.deal(sender, 10 ether);

        // Call the fallback via sending ether
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Only check when call succeeded
        vm.assume(success);

        uint256 balanceAfter = address(c).balance;

        // The rule: balance should never increase after a successful fallback call
        // In reference, it never increases; in mutant, it always increases by 10 ether
        assertTrue(balanceAfter <= balanceBefore);
    }
}

